import unittest

from solution import cumulative_total


class CumulativeTotalTests(unittest.TestCase):
    def test_zero_base_case(self):
        self.assertEqual(cumulative_total(0), 0)

    def test_positive_values(self):
        for n in (1, 2, 5, 10, 100):
            with self.subTest(n=n):
                self.assertEqual(cumulative_total(n), n * (n + 1) // 2)

    def test_rejects_negative_integer(self):
        with self.assertRaises(ValueError):
            cumulative_total(-1)

    def test_rejects_booleans_and_nonintegers(self):
        for bad in (True, False, 1.0, "3", None, [], 2 + 0j):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    cumulative_total(bad)


if __name__ == "__main__":
    unittest.main()

